#!/usr/bin/env bash
set -Eeuo pipefail

DEST="$HOME/grantbot_installers/grantbot_master_v1_consolidation.sh"
mkdir -p "$(dirname "$DEST")"

cat <<'GRANTBOT_MASTER_PAYLOAD' | base64 -d | gzip -dc > "$DEST"

GRANTBOT_MASTER_PAYLOAD

chmod +x "$DEST"
EXPECTED_SHA="40e1fdef22b84f480eb5e4516bf0c2583e59cbed10a6a01090d070af9b77405f"
ACTUAL_SHA="$(sha256sum "$DEST" | awk '{print $1}')"
if [[ "$ACTUAL_SHA" != "$EXPECTED_SHA" ]]; then
  echo "ERROR: Master installer checksum mismatch" >&2
  exit 1
fi
bash -n "$DEST"
echo "GRANTBOT MASTER BOOTSTRAP: VERIFIED"
echo "SAVED: $DEST"
echo "SHA256: $ACTUAL_SHA"
exec bash "$DEST"
